using System.Text.Json; namespace QuickHabits; internal sealed record Habit(int Id, string Name, DateOnly CreatedOn, bool Archived = false); internal sealed record HabitLog(int HabitId, DateOnly Day, string Note = ""); internal sealed record HabitData(List<Habit> Habits, List<HabitLog> Logs, int NextId); internal sealed record HabitStats(int ActiveCount, int ArchivedCount, int LoggedToday, int TotalLogs, int BestStreak); internal sealed record HabitView(Habit Habit, int CurrentStreak, int TotalLogs, DateOnly? LastLogged); internal sealed class HabitService(HabitData data) { public IReadOnlyList<Habit> ActiveHabits => data.Habits.Where(habit => !habit.Archived).OrderBy(habit => habit.Name, StringComparer.OrdinalIgnoreCase).ToList(); public IReadOnlyList<Habit> ArchivedHabits => data.Habits.Where(habit => habit.Archived).OrderBy(habit => habit.Name, StringComparer.OrdinalIgnoreCase).ToList(); public Habit Add(string name) { string cleanName = NormalizeName(name); EnsureUniqueName(cleanName); var habit = new Habit(data.NextId++, cleanName, DateOnly.FromDateTime(DateTime.Today)); data.Habits.Add(habit); return habit; } public bool LogToday(int habitId, string note = "") { Habit habit = Find(habitId); if (habit.Archived) throw new InvalidOperationException("Archived habits cannot be logged."); DateOnly today = DateOnly.FromDateTime(DateTime.Today); if (data.Logs.Any(log => log.HabitId == habitId && log.Day == today)) return false; data.Logs.Add(new HabitLog(habitId, today, NormalizeNote(note))); return true; } public Habit Rename(int habitId, string name) { Habit current = Find(habitId); Habit updated = current with { Name = NormalizeName(name) }; EnsureUniqueName(updated.Name, habitId); Replace(current, updated); return updated; } public Habit SetArchived(int habitId, bool archived) { Habit current = Find(habitId); if (current.Archived == archived) return current; Habit updated = current with { Archived = archived }; Replace(current, updated); return updated; } public HabitStats GetStats() { int active = data.Habits.Count(habit => !habit.Archived); DateOnly today = DateOnly.FromDateTime(DateTime.Today); int best = data.Habits.Select(habit => GetBestStreak(habit.Id)).DefaultIfEmpty().Max(); return new HabitStats(active, data.Habits.Count - active, data.Logs.Count(log => log.Day == today), data.Logs.Count, best); } public HabitView GetView(Habit habit) { List<DateOnly> days = GetUniqueDays(habit.Id); return new HabitView(habit, GetCurrentStreak(days), days.Count, days.Count == 0 ? null : days[0]); } public IReadOnlyList<HabitView> GetViews(bool includeArchived = false) { IEnumerable<Habit> source = includeArchived ? data.Habits : data.Habits.Where(habit => !habit.Archived); return source.OrderBy(habit => habit.Name, StringComparer.OrdinalIgnoreCase).Select(GetView).ToList(); } public IReadOnlyList<HabitView> Search(string query) { string term = query.Trim(); return GetViews().Where(view => term.Length == 0 || view.Habit.Name.Contains(term, StringComparison.OrdinalIgnoreCase)).ToList(); } private Habit Find(int habitId) => data.Habits.FirstOrDefault(habit => habit.Id == habitId) ?? throw new KeyNotFoundException($"Habit {habitId} was not found."); private void Replace(Habit oldHabit, Habit newHabit) => data.Habits[data.Habits.IndexOf(oldHabit)] = newHabit; private void EnsureUniqueName(string name, int? exceptId = null) { if (data.Habits.Any(habit => habit.Id != exceptId && string.Equals(habit.Name, name, StringComparison.OrdinalIgnoreCase))) throw new InvalidOperationException($"A habit named '{name}' already exists."); } private static string NormalizeName(string name) { string clean = name.Trim(); return clean.Length is >= 1 and <= 60 ? clean : throw new ArgumentException("Habit names must contain between 1 and 60 characters.", nameof(name)); } private static string NormalizeNote(string note) { string clean = note.Trim(); return clean.Length > 160 ? clean[..160] : clean; } private List<DateOnly> GetUniqueDays(int id) => data.Logs.Where(log => log.HabitId == id).Select(log => log.Day).Distinct().OrderDescending().ToList(); private int GetBestStreak(int habitId) { int best = 0, streak = 0; DateOnly? previous = null; foreach (DateOnly day in GetUniqueDays(habitId).Order()) { streak = previous is not null && day.DayNumber == previous.Value.DayNumber + 1 ? streak + 1 : 1; best = Math.Max(best, streak); previous = day; } return best; } private static int GetCurrentStreak(IReadOnlyList<DateOnly> days) { if (days.Count == 0) return 0; DateOnly today = DateOnly.FromDateTime(DateTime.Today); DateOnly expected = days[0] == today ? today : today.AddDays(-1); if (days[0] != expected) return 0; int streak = 0; foreach (DateOnly day in days) { if (day != expected) break; streak++; expected = expected.AddDays(-1); } return streak; } } internal sealed class HabitStore(string path) { private static readonly JsonSerializerOptions Options = new() { WriteIndented = true }; public string Path { get; } = System.IO.Path.GetFullPath(path); public HabitData Load() { if (!File.Exists(Path)) return new HabitData([], [], 1); HabitData? data = JsonSerializer.Deserialize<HabitData>(File.ReadAllText(Path), Options); if (data is null) throw new InvalidDataException($"The habit file '{Path}' is empty or invalid."); Validate(data); return data; } public void Save(HabitData data) { string? folder = System.IO.Path.GetDirectoryName(Path); if (folder is not null) Directory.CreateDirectory(folder); string temporaryPath = Path + ".tmp"; File.WriteAllText(temporaryPath, JsonSerializer.Serialize(data, Options)); File.Move(temporaryPath, Path, true); } private static void Validate(HabitData data) { if (data.NextId < 1 || data.Habits.Any(habit => habit.Id < 1) || data.Habits.Select(habit => habit.Id).Distinct().Count() != data.Habits.Count) throw new InvalidDataException("The habit file contains invalid or duplicate habit IDs."); HashSet<int> ids = data.Habits.Select(habit => habit.Id).ToHashSet(); if (data.Logs.Any(log => !ids.Contains(log.HabitId))) throw new InvalidDataException("The habit file contains a log for an unknown habit."); if (data.NextId <= data.Habits.Select(habit => habit.Id).DefaultIfEmpty().Max()) throw new InvalidDataException("The habit file's next ID is not greater than existing IDs."); } } internal sealed class ConsoleApp(HabitService service, HabitStore store, HabitData data) { private bool running = true; public void Run() { Console.OutputEncoding = System.Text.Encoding.UTF8; Console.WriteLine("Pocket Habits — 轻量习惯追踪器"); while (running) { ShowMenu(); Handle(Console.ReadLine()?.Trim()); } Console.WriteLine("数据已保存，再见！"); } private void Handle(string? choice) { switch (choice) { case "1": AddHabit(); break; case "2": ListHabits(); break; case "3": LogHabit(); break; case "4": ShowStats(); break; case "5": SearchHabits(); break; case "6": RenameHabit(); break; case "7": ToggleArchive(); break; case "0": case null: running = false; break; default: Console.WriteLine("请输入菜单中的数字。"); break; } } private void AddHabit() { string? name = Prompt("习惯名称"); if (name is null) return; RunAction(() => { Habit habit = service.Add(name); Save(); Console.WriteLine($"已创建 #{habit.Id}：{habit.Name}"); }); } private void ListHabits() { IReadOnlyList<HabitView> views = service.GetViews(); if (views.Count == 0) { Console.WriteLine("还没有习惯，先添加一个吧。"); return; } foreach (HabitView view in views) PrintView(view); } private void LogHabit() { int? id = PromptId("要打卡的习惯编号"); if (id is null) return; string note = Prompt("备注（可留空）") ?? ""; RunAction(() => { if (!service.LogToday(id.Value, note)) { Console.WriteLine("今天已经打过卡了。"); return; } Save(); Console.WriteLine("今日打卡成功。"); }); } private void ShowStats() { HabitStats stats = service.GetStats(); Console.WriteLine($"进行中：{stats.ActiveCount} | 已归档：{stats.ArchivedCount} | 今日打卡：{stats.LoggedToday}"); Console.WriteLine($"累计打卡：{stats.TotalLogs} | 最长连续记录：{stats.BestStreak} 天"); } private void SearchHabits() { string? query = Prompt("搜索关键词"); if (query is null) return; IReadOnlyList<HabitView> matches = service.Search(query); Console.WriteLine(matches.Count == 0 ? "没有匹配的习惯。" : $"找到 {matches.Count} 个习惯："); foreach (HabitView view in matches) PrintView(view); } private void RenameHabit() { int? id = PromptId("要重命名的习惯编号"); string? name = Prompt("新的名称"); if (id is null || name is null) return; RunAction(() => { Habit habit = service.Rename(id.Value, name); Save(); Console.WriteLine($"已重命名为：{habit.Name}"); }); } private void ToggleArchive() { int? id = PromptId("要归档或恢复的习惯编号"); if (id is null) return; RunAction(() => { Habit current = data.Habits.FirstOrDefault(habit => habit.Id == id.Value) ?? throw new KeyNotFoundException($"找不到习惯 #{id.Value}。"); Habit updated = service.SetArchived(id.Value, !current.Archived); Save(); Console.WriteLine(updated.Archived ? "习惯已归档。" : "习惯已恢复。"); }); } private void RunAction(Action action) { try { action(); } catch (ArgumentException error) { Console.WriteLine($"输入无效：{error.Message}"); } catch (InvalidOperationException error) { Console.WriteLine($"无法完成：{error.Message}"); } catch (KeyNotFoundException error) { Console.WriteLine(error.Message); } catch (IOException error) { Console.WriteLine($"文件操作失败：{error.Message}"); } catch (UnauthorizedAccessException error) { Console.WriteLine($"无权访问文件：{error.Message}"); } } private void Save() => store.Save(data); private static void PrintView(HabitView view) => Console.WriteLine($"#{view.Habit.Id,-3} {view.Habit.Name,-24} 连续 {view.CurrentStreak,2} 天 | 共 {view.TotalLogs,3} 次 | 最近：{view.LastLogged?.ToString("yyyy-MM-dd") ?? "尚无记录"}"); private static string? Prompt(string label) { Console.Write($"{label}："); return Console.ReadLine(); } private static int? PromptId(string label) { string? input = Prompt(label); if (int.TryParse(input, out int id) && id > 0) return id; if (input is not null) Console.WriteLine("请输入大于 0 的编号。"); return null; } private static void ShowMenu() { Console.WriteLine("\n1 添加   2 列表   3 今日打卡   4 统计"); Console.WriteLine("5 搜索   6 重命名   7 归档/恢复   0 退出 > "); } } internal static class Program { private static int Main(string[] args) { try { var store = new HabitStore(GetDataPath(args)); HabitData data = store.Load(); Console.WriteLine($"数据文件：{store.Path}"); new ConsoleApp(new HabitService(data), store, data).Run(); return 0; } catch (Exception error) { Console.Error.WriteLine($"启动失败：{error.Message}"); return 1; } } private static string GetDataPath(string[] args) => args.Length == 0 ? System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "QuickHabits", "habits.json") : args.Length == 2 && args[0] == "--data" ? args[1] : throw new ArgumentException("用法：QuickHabits [--data <文件路径>]"); }